lines += ['',f'BA direction is preserved in **{interp["BA_sign_preserved_markets"]}/5** markets; Accuracy direction in **{interp["Accuracy_sign_preserved_markets"]}/5**. These are newly calculated validation-selected counts, not the old4/5 statement. The reduced-overlap subset lowers mechanical label overlap but does not establish full independence. N47–49 gives low power; retain negative/sign-changing results.', '', '## 5. Nikkei High absolute primary metrics', '', f'Configuration: LNN MILD_WCE; N={int(h.N)}, positive-label rate={h.Positive_label_rate:.6f}. Primary LNN values are five-seed metric means, not an artificially enlarged585-row sample.','', '|Metric|LNN MILD_WCE seed mean|Persistence|Difference|','|---|---:|---:|---:|']
for r in panel.itertuples():lines.append(f'|{r.Metric}|{r.LNN_MILD_WCE_seed_mean:.6f}|{r.Persistence:.6f}|{r.Difference:+.6f}|')
lines += ['',f'Absolute LNN BA is {h.Balanced_Accuracy:.6f}, only modestly above0.5, while Persistence BA is {base.Balanced_Accuracy:.6f}. The large relative delta{h.Delta_BA:+.6f} partly reflects weak baseline performance; it is not evidence of high absolute predictive accuracy.', '', '## 6. New MILD_WCE time-series sensitivity', '', '|Metric|Observed delta|95% moving-block CI|Valid / requested|Invalid|','|---|---:|---|---:|---:|']
for r in bs.itertuples():lines.append(f'|{r.Metric}|{r.Estimate:+.6f}|[{r.CI_low:+.6f},{r.CI_high:+.6f}]|{r.Valid_resamples}/{r.Requested_resamples}|{r.Invalid_resamples}|')
